    r('groupes de Néron-Severi\n\\[\n\\operatorname{Pic}_{X_i/k_i}/\\operatorname{Pic}_{X_i/k_i}^\\circ\n\\]\ndes','groupes de Néron-Severi\n$\\operatorname{Pic}_{X_i/k_i}/\\operatorname{Pic}_{X_i/k_i}^\\circ$\ndes','beginning of (vi)','The quotient is inline.','structure')
